css:
.fx-dcurve .sec{position:relative;flex:1;display:grid;align-content:center;justify-items:center;text-align:center;gap:.8em;padding:5em 1.25em}
.fx-dcurve .sec h2{font-size:clamp(1.8em,4vw,2.8em);max-width:16em}.fx-dcurve .sec p{opacity:.75;max-width:44ch}
.fx-dcurve .sec .k{font-size:.75em;font-weight:700;letter-spacing:.16em;text-transform:uppercase;opacity:.7}
.fx-dcurve{--cv:clamp(36px,7vw,100px);display:flex;flex-direction:column;background:var(--surface)}
.fx-dcurve .s1{background:var(--surface);padding-bottom:calc(var(--cv) + 3em)}
.fx-dcurve .s2{z-index:2;margin-top:calc(var(--cv)*-1);padding:calc(var(--cv) + 3.5em) 1.25em calc(var(--cv) + 3.5em);background:var(--primary);color:var(--on-primary);border-radius:50% 50% 50% 50%/var(--cv) var(--cv) var(--cv) var(--cv)}
.fx-dcurve .s3{z-index:1;margin-top:calc(var(--cv)*-1);padding-top:calc(var(--cv) + 4em);background:color-mix(in srgb,var(--accent) 14%,var(--surface))}
.fx-dcurve .s2::after{content:"";position:absolute;left:12%;right:12%;bottom:calc(var(--cv)*.5);height:1px;background:color-mix(in srgb,var(--on-primary) 25%,transparent)}
